import { integer, pgTable, text, uniqueIndex, uuid } from "drizzle-orm/pg-core";

export const orders = pgTable("orders", {
  id: integer("id").primaryKey(),
  status: text("status").notNull(),
});

// Order lines; the id is generated by PostgreSQL. Nothing keys a line by
// the request that created it.
export const orderItems = pgTable("order_items", {
  id: uuid("id").primaryKey().defaultRandom(),
  orderId: integer("order_id").notNull(),
  requestId: text("request_id").notNull(),
  sku: text("sku").notNull(),
  qty: integer("qty").notNull(),
});

// The idempotent variant: one line per (request, sku).
export const requestItems = pgTable(
  "request_items",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orderId: integer("order_id").notNull(),
    requestId: text("request_id").notNull(),
    sku: text("sku").notNull(),
    qty: integer("qty").notNull(),
  },
  (t) => [uniqueIndex("request_items_request_sku").on(t.requestId, t.sku)],
);

// Payments; the id is generated by PostgreSQL.
export const payments = pgTable("payments", {
  id: uuid("id").primaryKey().defaultRandom(),
  orderId: integer("order_id").notNull(),
  amount: integer("amount").notNull(),
});
